import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        byte[] raw = System.in.readAllBytes();
        int n = raw.length;
        if (n > 0 && raw[n - 1] == '\n') n--;
        if (n > 0 && raw[n - 1] == '\r') n--;
        byte[] s = raw;
        // Try half lengths from largest to smallest; h consecutive compatible pairs at distance h give 2h.
        for (int h = n / 2; h > 0; h--) {
            int run = 0;
            for (int i = 0; i + h < n; i++) {
                run = (s[i] == s[i + h] || s[i] == '?' || s[i + h] == '?') ? run + 1 : 0;
                if (run >= h) {
                    System.out.println(2 * h);
                    return;
                }
            }
        }
        System.out.println(0);
    }
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
)

func main() {
	s, _ := io.ReadAll(bufio.NewReader(os.Stdin))
	n := len(s)
	if n > 0 && s[n-1] == '\n' {
		n--
	}
	if n > 0 && s[n-1] == '\r' {
		n--
	}
	// Try half lengths from largest to smallest; h consecutive compatible pairs at distance h give 2h.
	for h := n / 2; h > 0; h-- {
		run := 0
		for i := 0; i+h < n; i++ {
			if s[i] == s[i+h] || s[i] == '?' || s[i+h] == '?' {
				run++
			} else {
				run = 0
			}
			if run >= h {
				fmt.Println(2 * h)
				return
			}
		}
	}
	fmt.Println(0)
}
